powershell.exe -Command "
Add-Type @'
using System;
using System.Runtime.InteropServices;
public class Win32 {
    [DllImport(\"user32.dll\")]
    public static extern bool SetForegroundWindow(IntPtr hWnd);
    [DllImport(\"user32.dll\")]
    public static extern bool ShowWindow(IntPtr hWnd, int nCmdShow);
}
'@
\$proc = Get-Process -Name Obsidian | Where-Object { \$_.MainWindowHandle -ne 0 } | Select-Object -First 1
if (\$proc) {
    [Win32]::ShowWindow(\$proc.MainWindowHandle, 9)
    [Win32]::SetForegroundWindow(\$proc.MainWindowHandle)
    Write-Output \"Obsidian focused: PID \$(\$proc.Id), Window '\$(\$proc.MainWindowTitle)'\"
} else {
    Write-Output 'No Obsidian window with handle found'
}
"

