    public delegate bool EnumWindowsProc(IntPtr hWnd, IntPtr lParam);
    [DllImport("user32.dll")]
    public static extern bool EnumWindows(EnumWindowsProc lpEnumFunc, IntPtr lParam);
    [DllImport("user32.dll")]
    public static extern uint GetWindowThreadProcessId(IntPtr hWnd, out uint lpdwProcessId);
    [DllImport("user32.dll")]
    public static extern bool IsWindowVisible(IntPtr hWnd);

    [StructLayout(LayoutKind.Sequential)]
    public struct RECT {
        public int Left;
        public int Top;
        public int Right;
        public int Bottom;
    }
}
"@

# Find all Obsidian process IDs
$obsidianPids = Get-Process -Name Obsidian | Select-Object -ExpandProperty Id

# Find all visible windows belonging to Obsidian
$windows = @()
$callback = [Win32+EnumWindowsProc]{
    param($hWnd, $lParam)
    $pid = 0
    [Win32]::GetWindowThreadProcessId($hWnd, [ref]$pid) | Out-Null
    if ($obsidianPids -contains $pid -and [Win32]::IsWindowVisible($hWnd)) {
        $sb = New-Object System.Text.StringBuilder(256)
        [Win32]::GetWindowText($hWnd, $sb, 256) | Out-Null
        $title = $sb.ToString()
        if ($title.Length -gt 0) {
            $rect = New-Object Win32+RECT
